from itertools import permutations

names = ["Alice", "Bob", "Charlie", "David", "Ethan", "Frankie"]

def adj(seats, a, b):
    i, j = seats.index(a), seats.index(b)
    return (i - j) % 6 in (1, 5)

def dist(seats, a, b):
    i, j = seats.index(a), seats.index(b)
    d = (j - i) % 6
    return min(d, 6 - d)

def offset(seats, a, b):  # signed offset from a to b in index-increasing direction
    return (seats.index(b) - seats.index(a)) % 6

def solve(right_is_plus):
    """right_is_plus: seat index +1 is a person's 'right'."""
    left = -1 if right_is_plus else 1
    right = +1 if right_is_plus else -1
    out = []
    for rest in permutations([n for n in names if n != "Alice"]):
        seats = ["Alice"] + list(rest)
        # Alice & Frankie rival companies -> not adjacent
        if adj(seats, "Alice", "Frankie"):
            continue
        # Bob sits two seats to the left of Alice
        if offset(seats, "Alice", "Bob") != (2 * left) % 6:
            continue
        # Bob not adjacent to Ethan
        if adj(seats, "Bob", "Ethan"):
            continue
        # If Ethan across from Bob -> David two seats to the right of Alice
        if dist(seats, "Ethan", "Bob") == 3:
            if offset(seats, "Alice", "David") != (2 * right) % 6:
                continue
        # Frankie next to David or Ethan
        if not (adj(seats, "Frankie", "David") or adj(seats, "Frankie", "Ethan")):
            continue
        out.append(seats)
    return out

for convention in (True, False):
    sols = solve(convention)
    pairs = set()
    for s in sols:
        i = s.index("Charlie")
        nb = tuple(sorted([s[(i - 1) % 6], s[(i + 1) % 6]]))
        pairs.add(nb)
    print("right = index+1" if convention else "right = index-1",
          "-> solutions:", len(sols))
    for s in sols:
        print("  ", s)
    print("  Charlie neighbor pairs:", sorted(pairs))
    print()

